// Symptom: the landing brand and the admin label render at 8px.
// Brand is assumed to be the link named "dcortex" on the signed-out landing screen;
// admin label is assumed to be the admin label on the signed-in ops screen.
await page.goto('/login');
const brand = page.getByRole('link', { name: /dcortex/i }).first();
await expect(brand).toBeVisible();
await expect(brand).not.toHaveCSS('font-size', '8px');

await page.goto('/ops/radar');
const adminLabel = page.getByRole('navigation').getByText(/admin/i).first();
await expect(adminLabel).toBeVisible();
await expect(adminLabel).not.toHaveCSS('font-size', '8px');
